351	fn complete_arg_value(
352	    value: Result<&str, &OsStr>,
353	    arg: &clap::Arg,
354	    current_dir: Option<&std::path::Path>,
355	    arg_index: usize,
356	) -> Vec<CompletionCandidate> {
357	    let mut values = Vec::new();
358	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
359	
360	    let (prefix, value) =
361	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
362	
363	    let value_os = match value {
364	        Ok(value) => OsStr::new(value),
365	        Err(value_os) => value_os,
366	    };
367	
368	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
369	        values.extend(completer.complete_at(arg_index, value_os));
370	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
371	        values.extend(complete_value_candidates(
372	            value_os,
373	            completer.value_candidates(),
374	        ));
375	    } else if let Some(possible_values) = possible_values(arg) {
376	        if let Ok(value) = value {
377	            values.extend(complete_candidates_str(
378	                value,
379	                possible_value_candidates(possible_values),
380	            ));
381	        }
382	    } else {
383	        match arg.get_value_hint() {
384	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
385	                // Should not complete
386	            }
387	            clap::ValueHint::AnyPath => {
388	                values.extend(complete_path(value_os, current_dir, &|_| true));
389	            }
390	            clap::ValueHint::FilePath => {
391	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
392	            }
393	            clap::ValueHint::DirPath => {
394	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
395	            }
396	            clap::ValueHint::ExecutablePath => {
397	                use is_executable::IsExecutable;
398	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
399	            }
400	            clap::ValueHint::CommandName
401	            | clap::ValueHint::CommandString
402	            | clap::ValueHint::CommandWithArguments
403	            | clap::ValueHint::Username
404	            | clap::ValueHint::Hostname
405	            | clap::ValueHint::Url
406	            | clap::ValueHint::EmailAddress => {
407	                // No completion implementation
408	            }
409	            _ => {
410	                // Safe-ish fallback
411	                values.extend(complete_path(value_os, current_dir, &|_| true));
412	            }
413	        }
414	
415	        values.sort();
416	    }
417	
418	    if let Some(prefix) = prefix {
419	        values = values
420	            .into_iter()
421	            .map(|comp| comp.add_prefix(prefix))
422	            .collect();
423	    }
424	    values = values
425	        .into_iter()
426	        .map(|comp| {
427	            if comp.get_tag().is_some() {
428	                comp
429	            } else {
430	                comp.tag(Some(arg.to_string().into()))
431	            }
432	        })
433	        .collect();
434	
435	    debug!("complete_arg_value: values={values:?}");
436	    values
437	}
