450	fn complete_value_candidates(
451	    value: &OsStr,
452	    completer: &dyn ValueCandidates,
453	) -> Vec<CompletionCandidate> {
454	    debug!("complete_value_candidates: value={value:?}");
455	
456	    let mut values = completer.candidates();
457	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
458	    values
459	}
