480	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
481	    debug!(
482	        "complete_subcommand: cmd={:?}, value={:?}",
483	        cmd.get_name(),
484	        value
485	    );
486	
487	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
488	        .into_iter()
489	        .filter(|x| x.get_value().starts_with(value))
490	        .collect();
491	    if cmd.is_allow_external_subcommands_set() {
492	        let external_completer = cmd.get::<SubcommandCandidates>();
493	        if let Some(completer) = external_completer {
494	            scs.extend(complete_value_candidates_str(
495	                value,
496	                completer.value_candidates(),
497	            ));
498	        }
499	    }
500	
501	    scs.sort();
502	    scs.dedup();
503	    scs
504	}
