539	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
540	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
541	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
542	    debug!("shorts: name={}", p.get_name());
543	
544	    p.get_arguments()
545	        .filter_map(|a| {
546	            a.get_short_and_visible_aliases().map(|shorts| {
547	                shorts.into_iter().map(|s| {
548	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
549	                        a.get_help()
550	                            .cloned()
551	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
552	                    )
553	                })
554	            })
555	        })
556	        .flatten()
557	        .collect()
558	}
559	
560	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
561	    candidate
562	        .help(arg.get_help().cloned())
563	        .id(Some(format!("arg::{}", arg.get_id())))
564	        .tag(Some(
565	            arg.get_help_heading()
566	                .unwrap_or("Options")
567	                .to_owned()
568	                .into(),
569	        ))
570	        .display_order(Some(arg.get_display_order()))
571	        .hide(arg.is_hide_set())
572	}
