574	/// Get the possible values for completion
575	fn possible_values(
576	    a: &clap::Arg,
577	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
578	    if !a.get_num_args().expect("built").takes_values() {
579	        None
580	    } else {
581	        a.get_value_parser().possible_values()
582	    }
583	}
